// WF-08 entry. Resolve report scope from the job payload
// ({ report_type, period_start, period_end, retest }).
// Graceful stop when no job is claimed.
const j = $json;
if (!j.job_id) return { json: { skipped: true } };
const payload = (typeof j.payload_json === 'string' ? JSON.parse(j.payload_json) : j.payload_json) || {};
