const iso = (d) => d.toISOString().slice(0,10);
const end = iso(today);
const start = iso(new Date(today.getTime() - 7*86400000));
return {
  json: {
    hasJob: true,
    clientCode: j.client_code,
    jobId: j.job_id,
    reportType: payload.report_type || 'WEEKLY',
    periodStart: payload.period_start || start,
    periodEnd: payload.period_end || end,
    withRetest: payload.retest !== false
  }
};

